<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/config.php';
check_login();
$role=(string)($_SESSION['role_name']??$_SESSION['role']??'');
if(!in_array($role,['Administrator','Finance','Accountant'],true)){http_response_code(403);exit('Finance access required.');}
if(!isset($conn)||!$conn instanceof mysqli){http_response_code(500);exit('Database connection unavailable.');}
$year=filter_var($_GET['year']??date('Y'),FILTER_VALIDATE_INT);if($year===false||$year<2000||$year>2100)$year=(int)date('Y');
$type=(string)($_GET['entity_type']??'');if(!in_array($type,['','Project','Program'],true))$type='';
$stmt=$conn->prepare("SELECT b.entity_type,b.entity_id,b.activity_name,b.fiscal_year,b.currency,b.allocated_amount,CASE WHEN b.entity_type='Project' THEN p.project_code ELSE pr.program_code END entity_code,CASE WHEN b.entity_type='Project' THEN p.project_name ELSE pr.program_name END entity_name,COALESCE((SELECT SUM(r.requested_amount) FROM activity_event_requests r WHERE r.entity_type=b.entity_type AND r.entity_id=b.entity_id AND r.activity_name=b.activity_name AND r.currency=b.currency AND YEAR(r.start_date)=b.fiscal_year AND r.status IN ('Director Approval','Approved')),0) committed_amount FROM project_program_budget_lines b LEFT JOIN projects p ON b.entity_type='Project' AND p.project_id=b.entity_id LEFT JOIN programs pr ON b.entity_type='Program' AND pr.id=b.entity_id WHERE b.fiscal_year=? AND (?='' OR b.entity_type=?) ORDER BY b.entity_type,entity_code,b.activity_name");
$stmt->bind_param('iss',$year,$type,$type);$stmt->execute();$result=$stmt->get_result();$rows=$result->fetch_all(MYSQLI_ASSOC);$stmt->close();
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="finance-budget-report-'.$year.'.csv"');$out=fopen('php://output','wb');fputcsv($out,['entity_type','entity_code','entity_name','activity_name','fiscal_year','currency','allocated','committed','available']);foreach($rows as $row)fputcsv($out,[$row['entity_type'],$row['entity_code'],$row['entity_name'],$row['activity_name'],$row['fiscal_year'],$row['currency'],$row['allocated_amount'],$row['committed_amount'],(float)$row['allocated_amount']-(float)$row['committed_amount']]);fclose($out);exit;}
$totals=[];foreach($rows as $row){$currency=(string)$row['currency'];if(!isset($totals[$currency]))$totals[$currency]=['allocated'=>0.0,'committed'=>0.0];$totals[$currency]['allocated']+=(float)$row['allocated_amount'];$totals[$currency]['committed']+=(float)$row['committed_amount'];}
if(($_GET['export']??'')==='pdf'){
    $autoload=dirname(__DIR__).'/vendor/autoload.php';
    if(!is_file($autoload)){http_response_code(500);exit('PDF export is unavailable: the PDF library is not installed.');}
    require_once $autoload;
    if(!class_exists(\Dompdf\Dompdf::class)){http_response_code(500);exit('PDF export is unavailable: Dompdf is not installed.');}
    $escape=static fn($value):string=>htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
    $body='';foreach($rows as $row){$available=(float)$row['allocated_amount']-(float)$row['committed_amount'];$body.='<tr><td>'.$escape($row['entity_type']).'</td><td>'.$escape($row['entity_code']??'').'<br><small>'.$escape($row['entity_name']??'').'</small></td><td>'.$escape($row['activity_name']).'</td><td>'.$escape($row['currency']).'</td><td class="num">'.number_format((float)$row['allocated_amount'],2).'</td><td class="num">'.number_format((float)$row['committed_amount'],2).'</td><td class="num">'.number_format($available,2).'</td></tr>';}
    if($body==='')$body='<tr><td colspan="7">No budget lines match these filters.</td></tr>';
    $summary='';foreach($totals as $currency=>$total)$summary.='<div class="summary"><strong>'.number_format($total['allocated'],2).' '.$escape($currency).'</strong><span>Allocated</span><strong>'.number_format($total['committed'],2).' '.$escape($currency).'</strong><span>Committed</span><strong>'.number_format($total['allocated']-$total['committed'],2).' '.$escape($currency).'</strong><span>Available</span></div>';
    $html='<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#0d1117;font-size:9px}h1{color:#c2410c;font-size:20px;margin-bottom:4px}.meta{color:#4b5563;margin-bottom:16px}.summary{display:inline-block;width:31%;box-sizing:border-box;padding:10px;margin:0 1% 14px 0;background:#fff4ed;border:1px solid #ffc89e;border-radius:5px}.summary strong,.summary span{display:block;margin:3px 0}.summary span{font-size:8px;color:#4b5563}table{width:100%;border-collapse:collapse}th,td{padding:7px;border:1px solid #d1d5db;text-align:left;vertical-align:top}th{background:#fff4ed;color:#0d1117;font-size:8px;text-transform:uppercase}td.num{text-align:right;white-space:nowrap}small{color:#4b5563}</style></head><body><h1>Finance Budget Report</h1><div class="meta">Fiscal year: '.$year.' &nbsp;|&nbsp; Entity: '.($type===''?'All':$escape($type)).' &nbsp;|&nbsp; Generated: '.date('Y-m-d H:i').'</div>'.$summary.'<table><thead><tr><th>Type</th><th>Code / entity</th><th>Activity</th><th>Currency</th><th>Allocated</th><th>Committed</th><th>Available</th></tr></thead><tbody>'.$body.'</tbody></table></body></html>';
    $options=new \Dompdf\Options();$options->set('isRemoteEnabled',false);$pdf=new \Dompdf\Dompdf($options);$pdf->setPaper('A4','landscape');$pdf->loadHtml($html,'UTF-8');$pdf->render();
require_once __DIR__ . '/includes/pdf-branding.php';
ims_brand_pdf($pdf);$pdf->stream('finance-budget-report-'.$year.'.pdf',['Attachment'=>true]);exit;
}
$page_title='Finance Budget Reports';require_once __DIR__.'/includes/header.php';
function fr_h(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?>
<style>
.fr-page{max-width:1300px;margin:0 auto;padding:24px;display:grid;gap:22px;color:var(--ink-900)}.fr-page .fr-card{background:var(--surface-card);border:1px solid var(--border);border-radius:var(--radius-lg);padding:22px;box-shadow:var(--shadow-sm)}.fr-page form{display:flex;align-items:end;gap:14px;flex-wrap:wrap}.fr-page label{display:grid;gap:6px;font-weight:600;min-width:160px;color:var(--ink-700)}.fr-page input,.fr-page select{min-height:42px;padding:9px 12px;border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--surface-card);color:var(--ink-900);font:inherit}.fr-page button,.fr-page .fr-link{display:inline-flex;align-items:center;justify-content:center;min-height:42px;border:0;border-radius:var(--radius-sm);padding:9px 16px;background:var(--brand-600);color:var(--ink-0);font-weight:600;text-decoration:none;cursor:pointer}.fr-page button:hover,.fr-page .fr-link:hover{background:var(--brand-700)}.fr-page .fr-table-wrap{overflow:auto}.fr-page table{border-collapse:collapse;width:100%;min-width:800px}.fr-page th,.fr-page td{text-align:left;padding:12px;border-bottom:1px solid var(--border);color:var(--ink-700)}.fr-page th{font-size:.82rem;text-transform:uppercase;background:var(--surface-hover);color:var(--ink-900)}.fr-page td.num{text-align:right;font-variant-numeric:tabular-nums}@media(max-width:700px){.fr-page{padding:14px}.fr-page .fr-card{padding:16px}.fr-page form>*{width:100%}}
</style>
<div class="fr-page"><h1>Finance Budget Reports</h1><section class="fr-card"><form method="get"><label>Fiscal year<input type="number" min="2000" max="2100" name="year" value="<?=$year?>"></label><label>Entity type<select name="entity_type"><option value="" <?=$type===''?'selected':''?>>All</option><option value="Project" <?=$type==='Project'?'selected':''?>>Projects</option><option value="Program" <?=$type==='Program'?'selected':''?>>Programs</option></select></label><button type="submit">Apply filters</button><a class="fr-link" href="finance-reports?year=<?=$year?>&amp;entity_type=<?=rawurlencode($type)?>&amp;export=csv">Download CSV</a><a class="fr-link" href="finance-reports?year=<?=$year?>&amp;entity_type=<?=rawurlencode($type)?>&amp;export=pdf">Download PDF</a></form></section>
<section class="stats-grid reports-stats"><?php foreach($totals as $currency=>$t):?><div class="stat-card"><div class="stat-icon bg-blue"><i class="fas fa-coins" aria-hidden="true"></i></div><div class="stat-info"><span class="stat-label"><?=$year?> Allocated (<?=fr_h($currency)?>)</span><span class="stat-value"><?=number_format($t['allocated'],2)?></span></div></div><div class="stat-card"><div class="stat-icon bg-amber"><i class="fas fa-hand-holding-dollar" aria-hidden="true"></i></div><div class="stat-info"><span class="stat-label"><?=$year?> Committed (<?=fr_h($currency)?>)</span><span class="stat-value"><?=number_format($t['committed'],2)?></span></div></div><div class="stat-card"><div class="stat-icon bg-green"><i class="fas fa-wallet" aria-hidden="true"></i></div><div class="stat-info"><span class="stat-label"><?=$year?> Available (<?=fr_h($currency)?>)</span><span class="stat-value"><?=number_format($t['allocated']-$t['committed'],2)?></span></div></div><?php endforeach;?></section>
<section class="fr-card"><h2>Budget lines</h2><div class="fr-table-wrap"><table><thead><tr><th>Type</th><th>Code / entity</th><th>Activity</th><th>Year</th><th>Currency</th><th>Allocated</th><th>Committed</th><th>Available</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8">No budget lines match these filters.</td></tr><?php endif;?><?php foreach($rows as $row):$available=(float)$row['allocated_amount']-(float)$row['committed_amount'];?><tr><td><?=fr_h($row['entity_type'])?></td><td><strong><?=fr_h($row['entity_code']??'')?></strong><br><?=fr_h($row['entity_name']??'')?></td><td><?=fr_h($row['activity_name'])?></td><td><?=$row['fiscal_year']?></td><td><?=fr_h($row['currency'])?></td><td class="num"><?=number_format((float)$row['allocated_amount'],2)?></td><td class="num"><?=number_format((float)$row['committed_amount'],2)?></td><td class="num"><?=number_format($available,2)?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<?php require_once __DIR__.'/includes/footer.php'; ?>
